17	package podautoscaler
18	
19	import (
20		"context"
21		"fmt"
22		"strings"
23	
24		orchestrationv1alpha1 "github.com/vllm-project/aibrix/api/orchestration/v1alpha1"
25		metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
26		"k8s.io/apimachinery/pkg/apis/meta/v1/unstructured"
27		"k8s.io/apimachinery/pkg/runtime"
28		"k8s.io/apimachinery/pkg/runtime/schema"
29		"k8s.io/apimachinery/pkg/selection"
30		"k8s.io/client-go/util/retry"
31		"k8s.io/klog/v2"
32		"k8s.io/utils/ptr"
33	
34		autoscalingv1alpha1 "github.com/vllm-project/aibrix/api/autoscaling/v1alpha1"
35		"k8s.io/apimachinery/pkg/api/meta"
36		"k8s.io/apimachinery/pkg/labels"
37		"sigs.k8s.io/controller-runtime/pkg/client"
38	
39		"github.com/vllm-project/aibrix/pkg/controller/constants"
40	)
41	
42	const AutoscalingStormServiceModeAnnotationKey = "autoscaling.aibrix.ai/storm-service-mode"
43	
44	// WorkloadScale provides scaling operations for different workload types.
45	// It provides the mechanism to get/set replica counts on workload resources,
46	// while AutoScaler provides the intelligence to compute desired replica counts.
47	// The interface is stateless - all methods take PodAutoscaler as a parameter.
48	type WorkloadScale interface {
49		// Validate checks if the target is valid and scalable
50		Validate(ctx context.Context, pa *autoscalingv1alpha1.PodAutoscaler) error
51	
52		// GetCurrentReplicasFromScale extracts the current replica count from a scale object
53		GetCurrentReplicasFromScale(ctx context.Context, pa *autoscalingv1alpha1.PodAutoscaler, scale *unstructured.Unstructured) (int32, error)
54	
55		// SetDesiredReplicas updates the replica count
56		SetDesiredReplicas(ctx context.Context, pa *autoscalingv1alpha1.PodAutoscaler, replicas int32) error
57	
58		// GetPodSelectorFromScale extracts the label selector from an existing scale object
59		// For role-level scaling, it adds the role label requirement
60		// This avoids re-fetching the scale object when the controller already has it
61		GetPodSelectorFromScale(ctx context.Context, pa *autoscalingv1alpha1.PodAutoscaler, scale *unstructured.Unstructured) (labels.Selector, error)
62	}
63	
64	// workloadScale is a stateless implementation of WorkloadScale
65	type workloadScale struct {
66		client     client.Client
67		restMapper meta.RESTMapper
68	}
69	
70	// NewWorkloadScale creates a stateless WorkloadScale implementation
71	func NewWorkloadScale(
72		client client.Client,
73		restMapper meta.RESTMapper,
74	) WorkloadScale {
75		return &workloadScale{
76			client:     client,
77			restMapper: restMapper,
78		}
79	}
80	
81	func (s *workloadScale) Validate(ctx context.Context, pa *autoscalingv1alpha1.PodAutoscaler) error {
82		// Role-level scaling validation
83		if pa.Spec.SubTargetSelector != nil {
84			return s.validateRoleScaling(ctx, pa)
85		}
86	
87		// For generic scaling, just verify the resource exists
88		// We don't need to validate /scale subresource anymore
89		return nil
90	}
91	
92	func (s *workloadScale) validateRoleScaling(ctx context.Context, pa *autoscalingv1alpha1.PodAutoscaler) error {
93		ref := pa.Spec.ScaleTargetRef
94		if ref.Kind != "StormService" {
95			return fmt.Errorf("subTargetSelector only supported for StormService, got %q", ref.Kind)
96		}
97	
98		if pa.Spec.SubTargetSelector.RoleName == "" {
99			return fmt.Errorf("subTargetSelector.roleName must be set")
100		}
101	
102		ns := ref.Namespace
103		if ns == "" {
104			ns = pa.Namespace
105		}
106	
107		ss := &orchestrationv1alpha1.StormService{}
108		if err := s.client.Get(ctx, client.ObjectKey{Namespace: ns, Name: ref.Name}, ss); err != nil {
109			return fmt.Errorf("failed to get StormService: %w", err)
110		}
111	
112		if ss.Spec.Template.Spec == nil {
113			return fmt.Errorf("StormService template.spec is nil")
114		}
115	
116		// Check if role exists
117		for _, role := range ss.Spec.Template.Spec.Roles {
118			if role.Name == pa.Spec.SubTargetSelector.RoleName {
119				return nil
120			}
121		}
122	
123		return fmt.Errorf("role %q not found in StormService %s", pa.Spec.SubTargetSelector.RoleName, ref.Name)
124	}
125	
126	func (s *workloadScale) GetCurrentReplicasFromScale(ctx context.Context, pa *autoscalingv1alpha1.PodAutoscaler, scale *unstructured.Unstructured) (int32, error) {
127		// Role-level scaling
128		if s.isStormServiceWorkload(scale) && pa.Spec.SubTargetSelector != nil {
129			return s.getCurrentReplicasForRole(ctx, pa)
130		}
131	
132		// Generic scaling - extract from spec.replicas
133		currentReplicasInt64, found, err := unstructured.NestedInt64(scale.Object, "spec", "replicas")
134		if !found {
135			return 0, fmt.Errorf("the 'replicas' field was not found in the scale object")
136		}
137		if err != nil {
138			return 0, fmt.Errorf("failed to get 'replicas' from scale: %w", err)
139		}
140		return int32(currentReplicasInt64), nil
141	}
142	
143	func (s *workloadScale) getCurrentReplicasForRole(ctx context.Context, pa *autoscalingv1alpha1.PodAutoscaler) (int32, error) {
144		ref := pa.Spec.ScaleTargetRef
145		ns := ref.Namespace
146		if ns == "" {
147			ns = pa.Namespace
148		}
149	
150		ss := &orchestrationv1alpha1.StormService{}
151		if err := s.client.Get(ctx, client.ObjectKey{Namespace: ns, Name: ref.Name}, ss); err != nil {
152			return 0, err
153		}
154	
155		// replica mode, return the replicas directly
156		// we can not easily use `*ss.Spec.Replicas > 1` as condition since 1 could be pool or replica both case under autoscaling scenarios
157		if pa.Annotations[AutoscalingStormServiceModeAnnotationKey] == "replica" {
158			return *ss.Spec.Replicas, nil
159		}
160	
161		roleName := pa.Spec.SubTargetSelector.RoleName
162		for _, roleStatus := range ss.Status.RoleStatuses {
163			if roleStatus.Name == roleName {
164				return roleStatus.Replicas, nil
165			}
166		}
167	
168		// Fallback to spec
169		if ss.Spec.Template.Spec == nil {
170			return 0, fmt.Errorf("stormservice %s/%s template.spec is nil", ns, ref.Name)
171		}
172	
173		for _, role := range ss.Spec.Template.Spec.Roles {
174			if role.Name == roleName {
175				if role.Replicas != nil {
176					return *role.Replicas, nil
177				}
178				return 0, nil
179			}
180		}
181	
182		return 0, fmt.Errorf("role %s not found", roleName)
183	}
184	
185	func (s *workloadScale) SetDesiredReplicas(ctx context.Context, pa *autoscalingv1alpha1.PodAutoscaler, replicas int32) error {
186		// Role-level scaling
187		if pa.Spec.SubTargetSelector != nil {
188			return s.setDesiredReplicasForRole(ctx, pa, replicas)
189		}
190	
191		// Generic scaling - use RetryOnConflict to handle concurrent updates
192		ref := pa.Spec.ScaleTargetRef
193		ns := ref.Namespace
194		if ns == "" {
195			ns = pa.Namespace
196		}
197	
198		return retry.RetryOnConflict(retry.DefaultRetry, func() error {
199			// Parse API version
200			gv, err := schema.ParseGroupVersion(ref.APIVersion)
201			if err != nil {
202				return fmt.Errorf("invalid apiVersion %q: %w", ref.APIVersion, err)
203			}
204	
205			// Create unstructured object for the resource
206			scale := &unstructured.Unstructured{}
207			scale.SetGroupVersionKind(schema.GroupVersionKind{
208				Group:   gv.Group,
209				Version: gv.Version,
210				Kind:    ref.Kind,
211			})
212	
213			// Get current resource
214			if err := s.client.Get(ctx, client.ObjectKey{Namespace: ns, Name: ref.Name}, scale); err != nil {
215				return err
216			}
217	
218			// Update replicas field
219			if err := unstructured.SetNestedField(scale.Object, int64(replicas), "spec", "replicas"); err != nil {
220				return fmt.Errorf("failed to set replicas field: %w", err)
221			}
222	
223			// Update the resource
224			// Note: we have choice to use scale api, but it requires /scale RBAC, to simplify the scenario, let's use current way
225			if err := s.client.Update(ctx, scale); err != nil {
226				return err
227			}
228	
229			klog.InfoS("Scaled resource", "kind", ref.Kind, "name", ref.Name, "ns", ns, "replicas", replicas)
230			return nil
231		})
232	}
233	
234	func (s *workloadScale) setDesiredReplicasForRole(ctx context.Context, pa *autoscalingv1alpha1.PodAutoscaler, replicas int32) error {
235		ref := pa.Spec.ScaleTargetRef
236		ns := ref.Namespace
237		if ns == "" {
238			ns = pa.Namespace
239		}
240		roleName := pa.Spec.SubTargetSelector.RoleName
241	
242		// Use RetryOnConflict to handle concurrent updates
243		return retry.RetryOnConflict(retry.DefaultRetry, func() error {
244			cur := &orchestrationv1alpha1.StormService{}
245			if err := s.client.Get(ctx, client.ObjectKey{Namespace: ns, Name: ref.Name}, cur); err != nil {
246				return err
247			}
248			upd := cur.DeepCopy()
249			// TODO: tricky part. it's hard to know replica=1 is pooling or replica mode, we can use autoscaling to limit it.
250			// we can extract the method and fallback to ss object annotation to check as well.
251			if pa.Annotations[AutoscalingStormServiceModeAnnotationKey] == "replica" {
252				upd.Spec.Replicas = ptr.To(replicas)
253				return s.client.Patch(ctx, upd, client.MergeFrom(cur))
254			}
255			// handle pool mode
256			if upd.Spec.Template.Spec == nil {
257				return fmt.Errorf("template.spec is nil")
258			}
259			found := false
260			for i := range upd.Spec.Template.Spec.Roles {
261				if upd.Spec.Template.Spec.Roles[i].Name == roleName {
262					upd.Spec.Template.Spec.Roles[i].Replicas = ptr.To(replicas)
263					found = true
264					break
265				}
266			}
267			if !found {
268				return fmt.Errorf("role %q not found", roleName)
269			}
270			return s.client.Patch(ctx, upd, client.MergeFrom(cur))
271		})
272	}
273	
274	func (s *workloadScale) getPodSelectorForRole(ctx context.Context, pa *autoscalingv1alpha1.PodAutoscaler) (labels.Selector, error) {
275		ref := pa.Spec.ScaleTargetRef
276		ns := ref.Namespace
277		if ns == "" {
278			ns = pa.Namespace
279		}
280	
281		ss := &orchestrationv1alpha1.StormService{}
282		if err := s.client.Get(ctx, client.ObjectKey{Namespace: ns, Name: ref.Name}, ss); err != nil {
283			klog.ErrorS(err, "Failed to get StormService", "namespace", ns, "name", ref.Name)
284			return nil, err
285		}
286		// Note: it's possible user just configure StormService without role name, in that case, we just aggregate all the pods.
287		labelSelector := labels.SelectorFromSet(labels.Set{
288			constants.StormServiceNameLabelKey: ss.Name,
289		})
290	
291		roleName := ""
292		if pa.Spec.SubTargetSelector != nil && pa.Spec.SubTargetSelector.RoleName != "" {
293			req, err := labels.NewRequirement(constants.RoleNameLabelKey, selection.Equals, []string{pa.Spec.SubTargetSelector.RoleName})
294			if err != nil {
295				return nil, err
296			}
297			labelSelector = labelSelector.Add(*req)
298			roleName = pa.Spec.SubTargetSelector.RoleName
299		}
300	
301		// ss.Spec.Template.Spec may be nil in test cases
302		if ss.Spec.Template.Spec != nil {
303			for _, role := range ss.Spec.Template.Spec.Roles {
304				// skip if roleName specified but not equal
305				if roleName != "" && role.Name != roleName {
306					continue
307				}
308	
309				// add new selector for podGroup index 0, based on #1704
310				if role.PodGroupSize != nil && *role.PodGroupSize > 1 {
311					req, err := labels.NewRequirement(constants.PodGroupIndexLabelKey, selection.Equals, []string{"0"})
312					if err != nil {
313						return nil, err
314					}
315					labelSelector = labelSelector.Add(*req)
316				}
317			}
318		}
319		return labelSelector, nil
320	}
321	
322	func (s *workloadScale) GetPodSelectorFromScale(ctx context.Context, pa *autoscalingv1alpha1.PodAutoscaler, scale *unstructured.Unstructured) (labels.Selector, error) {
323		// For role-level scaling, get StormService and add role requirement
324		isStormService := s.isStormServiceWorkload(scale)
325		if isStormService {
326			return s.getPodSelectorForRole(ctx, pa)
327		}
328	
329		// For generic scaling, extract from scale object
330		// Try status.selector first (string format used by /scale subresource)
331		statusSelector, found, err := unstructured.NestedString(scale.Object, "status", "selector")
332		if err == nil && found && strings.TrimSpace(statusSelector) != "" {
333			return labels.Parse(statusSelector)
334		}
335	
336		// Try spec.selector (LabelSelector format)
337		selectorMap, found, err := unstructured.NestedMap(scale.Object, "spec", "selector")
338		if err != nil {
339			return nil, fmt.Errorf("failed to get 'spec.selector' from scale: %w", err)
340		}
341		if !found {
342			// No selector found, return error
343			return nil, fmt.Errorf("scale object %q is missing spec.selector", scale.GetName())
344		}
345	
346		// Convert selectorMap to a *metav1.LabelSelector object
347		selector := &metav1.LabelSelector{}
348		err = runtime.DefaultUnstructuredConverter.FromUnstructured(selectorMap, selector)
349		if err != nil {
350			return nil, fmt.Errorf("failed to convert 'spec.selector' to LabelSelector: %w", err)
351		}
352	
353		labelsSelector, err := metav1.LabelSelectorAsSelector(selector)
354		if err != nil {
355			return nil, fmt.Errorf("failed to convert LabelSelector to labels.Selector: %w", err)
356		}
357	
358		return labelsSelector, nil
359	}
360	
361	func (s *workloadScale) isStormServiceWorkload(scale *unstructured.Unstructured) bool {
362		isStormService := false
363		if scale.GetAPIVersion() == "orchestration.aibrix.ai/v1alpha1" && scale.GetKind() == "StormService" {
364			isStormService = true
365		}
366		return isStormService
367	}
368	
369	// isStormServiceWorkload checks if the given scale object is a StormService
370

